    "tutorial.tasks.loc": "Barre latérale → Tâches",
    "tutorial.tasks.p1": "Faites glisser les tâches pour les réorganiser, cliquez pour les modifier, tout reste synchronisé.",
    "tutorial.tasks.p2": "Les priorités, les dates d’échéance et les statuts maintiennent les choses en ordre.",
    "tutorial.tasks.p3": "Noor peut créer, réaliser et replanifier des tâches pour vous.",
    "tutorial.tasks.title": "Tâches",
    "tutorial.welcome.desc": "Un espace de travail privé et local avec un seul travail : vous aide à réfléchir, planifier et créer. Il se charge instantanément, fonctionne hors ligne et reste sur votre appareil jusqu'à ce que vous choisissiez de le synchroniser.",
